    public override Dictionary<string, object> parseCurrency(object rawCurrency)
    {
        string? id = this.safeString(rawCurrency, "symbol");
        string? code = this.safeCurrencyCode(id);
        string? name = this.safeString(rawCurrency, "name");
        Dictionary<string, object> networks = new Dictionary<string, object>() {};
        List<object> chains = this.safeList(rawCurrency, "binding_gateways", new List<object>() {});
        string? currencyMaxPrecision = this.parsePrecision(this.safeString2(rawCurrency, "withdrawal_scale", "scale"));
        for (int j = 0; j < chains.Count; j++)
        {
            IDictionary<string, object> chain = ((IDictionary<string, object>)chains[j]);
            string? networkId = this.safeString(chain, "gateway_name");
            string? networkCode = this.networkIdToCode(networkId, code);
            bool? deposit = this.safeBool(chain, "is_deposit_enabled");
            bool? withdraw = this.safeBool(chain, "is_withdrawal_enabled");
            string? minDepositAmount = this.safeString(chain, "min_deposit_amount");
            string? minWithdrawalAmount = this.safeString(chain, "min_withdrawal_amount");
            string? withdrawalFee = this.safeString(chain, "withdrawal_fee");
            string? precision = this.parsePrecision(this.safeString2(chain, "withdrawal_scale", "scale"));
            if ((networkCode != null))
            {
                networks[(string)networkCode] = new Dictionary<string, object>() {
                    { "id", networkId },
                    { "network", networkCode },
                    { "margin", null },
                    { "deposit", deposit },
                    { "withdraw", withdraw },
                    { "active", null },
                    { "fee", this.parseNumber(withdrawalFee) },
                    { "precision", this.parseNumber(precision) },
                    { "limits", new Dictionary<string, object>() {
                        { "deposit", new Dictionary<string, object>() {
                            { "min", minDepositAmount },
                            { "max", null },
                        } },
                        { "withdraw", new Dictionary<string, object>() {
                            { "min", minWithdrawalAmount },
                            { "max", null },
                        } },
                    } },
                    { "info", chain },
                };
            }
        }
        int chainLength = chains.Count;
        string? type = null;
        if ((this.safeBool(rawCurrency, "is_fiat") == true))
        {
            type = "fiat";
        } else if ((chainLength == 0))
        {
            if (this.isLeveragedCurrency(id))
            {
                type = "leveraged";
            } else
            {
                type = "other";
            }
        } else
        {
            type = "crypto";
        }
        return this.safeCurrencyStructure(new Dictionary<string, object>() {
            { "id", id },
            { "code", code },
            { "info", rawCurrency },
            { "name", name },
            { "type", type },
            { "active", null },
            { "deposit", null },
            { "withdraw", null },
            { "fee", null },
            { "precision", this.parseNumber(currencyMaxPrecision) },
            { "limits", new Dictionary<string, object>() {
                { "amount", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
                { "withdraw", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
            } },
            { "networks", networks },
        });
    }

    /**
     * @method
     * @name bigone#fetchMarkets
     * @description retrieves data on all markets for bigone
     * @see https://open.big.one/docs/spot_asset_pair.html
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> promises = new List<object> {this.publicGetAssetPairs(parameters), this.contractPublicGetSymbols(parameters)};
        List<object> promisesResult = await promiseAll(promises);
        IDictionary<string, object> response = this.safeDict(promisesResult, 0);
        object contractResponse = (promisesResult != null && 1 < promisesResult.Count ? promisesResult[1] : null);
        //
        //     {
        //         "code":0,
        //         "data":[
        //             {
        //                 "id":"01e48809-b42f-4a38-96b1-c4c547365db1",
        //                 "name":"PCX-BTC",
        //                 "quote_scale":7,
        //                 "quote_asset":{
        //                     "id":"0df9c3c3-255a-46d7-ab82-dedae169fba9",
        //                     "symbol":"BTC",
        //                     "name":"Bitcoin",
        //                 },
        //                 "base_asset":{
        //                     "id":"405484f7-4b03-4378-a9c1-2bd718ecab51",
        //                     "symbol":"PCX",
        //                     "name":"ChainX",
        //                 },
        //                 "base_scale":3,
        //                 "min_quote_value":"0.0001",
        //                 "max_quote_value":"35"
        //             },
        //         ]
        //     }
        //
        //
        //    [
        //        {
        //            "baseCurrency": "BTC",
        //            "multiplier": 1,
        //            "enable": true,
        //            "priceStep": 0.5,
        //            "maxRiskLimit": 1000,
        //            "pricePrecision": 1,
        //            "maintenanceMargin": 0.00500,
        //            "symbol": "BTCUSD",
        //            "valuePrecision": 4,
        //            "minRiskLimit": 100,
        //            "riskLimit": 100,
        //            "isInverse": true,
        //            "riskStep": 1,
        //            "settleCurrency": "BTC",
        //            "baseName": "Bitcoin",
        //            "feePrecision": 8,
        //            "priceMin": 0.5,
        //            "priceMax": 1E+6,
        //            "initialMargin": 0.01000,
        //            "quoteCurrency": "USD"
        //        },
        //        ...
        //    ]
        //
        List<object> markets = this.safeList(response, "data", new List<object>() {});
        List<object> result = new List<object>() {};
        for (int i = 0; i < markets.Count; i++)
        {
            object market = markets[i];
            IDictionary<string, object> baseAsset = this.safeDict(market, "base_asset", new Dictionary<string, object>() {});
            IDictionary<string, object> quoteAsset = this.safeDict(market, "quote_asset", new Dictionary<string, object>() {});
            string? baseId = this.safeString(baseAsset, "symbol");
            string? quoteId = this.safeString(quoteAsset, "symbol");
            string? bs = this.safeCurrencyCode(baseId);
            string? quote = this.safeCurrencyCode(quoteId);
            if (((bs == null)) || ((quote == null)))
            {
                continue;
            }
            result.Add(this.safeMarketStructure(new Dictionary<string, object>() {
                { "id", this.safeString(market, "name") },
                { "uuid", this.safeString(market, "id") },
                { "symbol", ((bs + "/") + quote) },
                { "base", bs },
                { "quote", quote },
                { "settle", null },
                { "baseId", baseId },
                { "quoteId", quoteId },
                { "settleId", null },
                { "type", "spot" },
                { "spot", true },
                { "margin", false },
                { "swap", false },
                { "future", false },
                { "option", false },
                { "active", true },
                { "contract", false },
                { "linear", null },
                { "inverse", null },
                { "contractSize", null },
                { "expiry", null },
                { "expiryDatetime", null },
                { "strike", null },
                { "optionType", null },
                { "precision", new Dictionary<string, object>() {
                    { "amount", this.parseNumber(this.parsePrecision(this.safeString(market, "base_scale"))) },
                    { "price", this.parseNumber(this.parsePrecision(this.safeString(market, "quote_scale"))) },
                } },
                { "limits", new Dictionary<string, object>() {
                    { "leverage", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "amount", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "price", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "cost", new Dictionary<string, object>() {
                        { "min", this.safeNumber(market, "min_quote_value") },
                        { "max", this.safeNumber(market, "max_quote_value") },
                    } },
                } },
                { "created", null },
                { "info", market },
            }));
        }
        IList<object> contractMarkets = this.toArray(contractResponse);
        for (int i = 0; i < (contractMarkets?.Count ?? 0); i++)
        {
            object market = contractMarkets[i];
            string? baseId = this.safeString(market, "baseCurrency");
            string? quoteId = this.safeString(market, "quoteCurrency");
            string? settleId = this.safeString(market, "settleCurrency");
            string? marketId = this.safeString(market, "symbol");
            string? bs = this.safeCurrencyCode(baseId);
            string? quote = this.safeCurrencyCode(quoteId);
            if (((bs == null)) || ((quote == null)))
            {
                continue;
            }
            string? settle = this.safeCurrencyCode(settleId);
            bool? inverse = this.safeBool(market, "isInverse");
            result.Add(this.safeMarketStructure(new Dictionary<string, object>() {
                { "id", marketId },
                { "symbol", ((((bs + "/") + quote) + ":") + settle) },
                { "base", bs },
                { "quote", quote },
                { "settle", settle },
                { "baseId", baseId },
                { "quoteId", quoteId },
                { "settleId", settleId },
                { "type", "swap" },
                { "spot", false },
                { "margin", false },
                { "swap", true },
                { "future", false },
                { "option", false },
                { "active", this.safeBool(market, "enable") },
                { "contract", true },
                { "linear", ((inverse != true)) },
                { "inverse", inverse },
                { "contractSize", this.safeNumber(market, "multiplier") },
                { "expiry", null },
                { "expiryDatetime", null },
                { "strike", null },
                { "optionType", null },
                { "precision", new Dictionary<string, object>() {
                    { "amount", this.parseNumber(this.parsePrecision(this.safeString(market, "valuePrecision"))) },
                    { "price", this.parseNumber(this.parsePrecision(this.safeString(market, "pricePrecision"))) },
                } },
                { "limits", new Dictionary<string, object>() {
                    { "leverage", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "amount", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "price", new Dictionary<string, object>() {
                        { "min", this.safeNumber(market, "priceMin") },
                        { "max", this.safeNumber(market, "priceMax") },
                    } },
                    { "cost", new Dictionary<string, object>() {
                        { "min", this.safeNumber(market, "initialMargin") },
                        { "max", null },
                    } },
                } },
                { "info", market },
            }));
        }
        return ccxt.BaseExchange.ToMarketInterfaceList(result);
    }

    public override Dictionary<string, object> parseTicker(object ticker, object market = null)
    {
        //
        // spot
        //
        //    {
        //        "asset_pair_name": "ETH-BTC",
        //        "bid": {
        //            "price": "0.021593",
        //            "order_count": 1,
        //            "quantity": "0.20936"
        //        },
        //        "ask": {
        //            "price": "0.021613",
        //            "order_count": 1,
        //            "quantity": "2.87064"
        //        },
        //        "open": "0.021795",
        //        "high": "0.021795",
        //        "low": "0.021471",
        //        "close": "0.021613",
        //        "volume": "117078.90431",
        //        "daily_change": "-0.000182"
        //    }
        //
        // contract
        //
        //    {
        //        "usdtPrice": 1.00031998,
        //        "symbol": "BTCUSD",
        //        "btcPrice": 34700.4,
        //        "ethPrice": 1787.83,
        //        "nextFundingRate": 0.00010,
        //        "fundingRate": 0.00010,
        //        "latestPrice": 34708.5,
        //        "last24hPriceChange": 0.0321,
        //        "indexPrice": 34700.4,
        //        "volume24h": 261319063,
        //        "turnover24h": 8204.129380685496,
        //        "nextFundingTime": 1698285600000,
        //        "markPrice": 34702.4646738,
        //        "last24hMaxPrice": 35127.5,
        //        "volume24hInUsd": 0.0,
        //        "openValue": 32.88054722085945,
        //        "last24hMinPrice": 33552.0,
        //        "openInterest": 1141372.0
        //    }
        //
        string marketType = "swap";
        if ((ticker != null && ((IDictionary<string, object>)ticker).ContainsKey("asset_pair_name")))
        {
            marketType = "spot";
        }
        string? marketId = this.safeString2(ticker, "asset_pair_name", "symbol");
        string? symbol = this.safeSymbol(marketId, market, "-", marketType);
        string? close = this.safeString2(ticker, "close", "latestPrice");
        IDictionary<string, object> bid = this.safeDict(ticker, "bid", new Dictionary<string, object>() {});
        IDictionary<string, object> ask = this.safeDict(ticker, "ask", new Dictionary<string, object>() {});
        return this.safeTicker(new Dictionary<string, object>() {
            { "symbol", symbol },
            { "timestamp", null },
            { "datetime", null },
            { "high", this.safeString2(ticker, "high", "last24hMaxPrice") },
            { "low", this.safeString2(ticker, "low", "last24hMinPrice") },
            { "bid", this.safeString(bid, "price") },
            { "bidVolume", this.safeString(bid, "quantity") },
            { "ask", this.safeString(ask, "price") },
            { "askVolume", this.safeString(ask, "quantity") },
            { "vwap", null },
            { "open", this.safeString(ticker, "open") },
            { "close", close },
            { "last", close },
            { "previousClose", null },
            { "change", this.safeString(ticker, "daily_change") },
            { "percentage", null },
            { "average", null },
            { "baseVolume", this.safeString2(ticker, "volume", "volume24h") },
            { "quoteVolume", this.safeString(ticker, "volume24hInUsd") },
            { "markPrice", this.safeString(ticker, "markPrice") },
            { "indexPrice", this.safeString(ticker, "indexPrice") },
            { "info", ticker },
        }, market);
    }

    /**
     * @method
     * @name bigone#fetchTicker
     * @description fetches a price ticker, a statistical calculation with the information calculated over the past 24 hours for a specific market
     * @see https://open.big.one/docs/spot_tickers.html
     * @param {string} symbol unified symbol of the market to fetch the ticker for
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [ticker structure]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public async override Task<ccxt.Ticker> FetchTicker(string symbol, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        IList<object> typeparamsMarketTypeVariable = (IList<object>)this.handleMarketTypeAndParams("fetchTicker", market, parameters);
        string? type = (string)typeparamsMarketTypeVariable[0];
        IDictionary<string, object> paramsMarketType = ((IDictionary<string, object>)typeparamsMarketTypeVariable[1]);
        if ((type == "spot"))
        {
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "asset_pair_name", (market.ContainsKey("id") ? market["id"] : null) },
            };
            Dictionary<string, object> response = await this.publicGetAssetPairsAssetPairNameTicker(this.extend(request, paramsMarketType));
            //
            //     {
            //         "code":0,
            //         "data":{
            //             "asset_pair_name":"ETH-BTC",
            //             "bid":{"price":"0.021593","order_count":1,"quantity":"0.20936"},
            //             "ask":{"price":"0.021613","order_count":1,"quantity":"2.87064"},
            //             "open":"0.021795",
            //             "high":"0.021795",
            //             "low":"0.021471",
            //             "close":"0.021613",
            //             "volume":"117078.90431",
            //             "daily_change":"-0.000182"
            //         }
            //     }
            //
            IDictionary<string, object> ticker = this.safeDict(response, "data", new Dictionary<string, object>() {});
            return ccxt.BaseExchange.ToTicker(this.parseTicker(ticker, market));
        } else
        {
            Dictionary<string, object> tickers = ccxt.BaseExchange.FromTickers(await this.FetchTickers(new List<object>() {symbol}, paramsMarketType));
            return ccxt.BaseExchange.ToTicker(this.safeValue(tickers, symbol));
        }
    }

    /**
     * @method
     * @name bigone#fetchTickers
     * @description fetches price tickers for multiple markets, statistical information calculated over the past 24 hours for each market
     * @see https://open.big.one/docs/spot_tickers.html
     * @param {string[]} [symbols] unified symbols of the markets to fetch the ticker for, all market tickers are returned if not assigned
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a dictionary of [ticker structures]{@link https://docs.ccxt.com/?id=ticker-structure}
     */
    public async override Task<ccxt.Tickers> FetchTickers(IList<object> symbols = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        IDictionary<string, object> market = null;
        string? symbol = this.safeString(symbols, 0);
        if ((symbol != null))
        {
            market = this.market(symbol);
        }
        IList<object> typeparamsMarketTypeVariable = (IList<object>)this.handleMarketTypeAndParams("fetchTickers", market, parameters);
        string? type = (string)typeparamsMarketTypeVariable[0];
        IDictionary<string, object> paramsMarketType = ((IDictionary<string, object>)typeparamsMarketTypeVariable[1]);
        bool isSpot = (type == "spot");
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        IList<object> symbolsNormalized = this.marketSymbols(symbols);
        IList<object> data = null;
        if (isSpot)
        {
            if ((symbolsNormalized != null))
            {
                IList<object> ids = this.marketIds(symbolsNormalized);
                request["pair_names"] = String.Join(",", ids.ToArray());
            }
            Dictionary<string, object> response = await this.publicGetAssetPairsTickers(this.extend(request, paramsMarketType));
            //
            //    {
            //        "code": 0,
            //        "data": [
            //            {
            //                "asset_pair_name": "PCX-BTC",
            //                "bid": {
            //                    "price": "0.000234",
            //                    "order_count": 1,
            //                    "quantity": "0.518"
            //                },
            //                "ask": {
            //                    "price": "0.0002348",
            //                    "order_count": 1,
            //                    "quantity": "2.348"
            //                },
            //                "open": "0.0002343",
            //                "high": "0.0002348",
            //                "low": "0.0002162",
            //                "close": "0.0002348",
            //                "volume": "12887.016",
            //                "daily_change": "0.0000005"
            //            },
            //            ...
            //        ]
            //    }
            //
            data = this.safeList(response, "data", new List<object>() {});
        } else
        {
            List<object> instruments = await this.contractPublicGetInstruments(paramsMarketType);
            data = this.toArray(instruments);
        }
        Dictionary<string, object> tickers = this.parseTickers(data, symbolsNormalized);
        return ccxt.BaseExchange.ToTickers(this.filterByArrayTickers(tickers, "symbol", symbolsNormalized));
    }

    /**
     * @method
     * @name bigone#fetchTime
     * @description fetches the current integer timestamp in milliseconds from the exchange server
     * @see https://open.big.one/docs/spot_ping.html
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {int} the current integer timestamp in milliseconds from the exchange server
     */
    public async override Task<Int64> FetchTime(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        Dictionary<string, object> response = await this.publicGetPing(parameters);
        //
        //     {
        //         "data": {
        //             "timestamp": 1527665262168391000
        //         }
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        Int64? timestamp = this.safeInteger(data, "Timestamp");
        if ((timestamp == null))
        {
            throw new ExchangeError ((this.id + " fetchTime() missing timestamp")) ;
        }
        return ccxt.BaseExchange.ToInt64Value(this.parseToInt((timestamp / 1000000)));
    }

    /**
     * @method
     * @name bigone#fetchOrderBook
     * @description fetches information on open orders with bid (buy) and ask (sell) prices, volumes and other data
     * @see https://open.big.one/docs/contract_misc.html#get-orderbook-snapshot
     * @param {string} symbol unified symbol of the market to fetch the order book for
     * @param {int} [limit] the maximum amount of order book entries to return
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [order book structure]{@link https://docs.ccxt.com/?id=order-book-structure}
     */
    public async override Task<ccxt.OrderBook> FetchOrderBook(string symbol, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> market = this.market(symbol);
        Dictionary<string, object> response = null;
        if ((((market.ContainsKey("contract") ? market["contract"] : null) as bool?) == true))
        {
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "symbol", (market.ContainsKey("id") ? market["id"] : null) },
            };
            response = await this.contractPublicGetDepthSymbolSnapshot(this.extend(request, parameters));
            //
            //    {
            //        bids: {
            //            '20000': '20',
            //            ...
            //            '34552': '64851',
            //            '34526.5': '59594',
            //            ...
            //            '34551.5': '29711'
            //        },
            //        asks: {
            //            '34557': '34395',
            //            ...
            //            '40000': '20',
            //            '34611.5': '56024',
            //            ...
            //            '34578.5': '66367'
            //        },
            //        to: '59737174',
            //        lastPrice: '34554.5',
            //        bestPrices: {
            //            ask: '34557.0',
            //            bid: '34552.0'
            //        },
            //        from: '0'
            //    }
            //
            return ccxt.BaseExchange.ToOrderBook(this.parseContractOrderBook(response, (market.ContainsKey("symbol") ? market["symbol"] : null), limit));
        } else
        {
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "asset_pair_name", (market.ContainsKey("id") ? market["id"] : null) },
            };
            if ((limit != null))
            {
                request["limit"] = limit; // default 50, max 200
            }
            response = await this.publicGetAssetPairsAssetPairNameDepth(this.extend(request, parameters));
            //
            //     {
            //         "code":0,
            //         "data": {
            //             "asset_pair_name": "EOS-BTC",
            //             "bids": [
            //                 { "price": "42", "order_count": 4, "quantity": "23.33363711" }
