    public virtual string? parseType(string? type)
    {
        Dictionary<string, object> types = new Dictionary<string, object>() {
            { "STOP_LIMIT", "limit" },
            { "STOP_MARKET", "market" },
            { "LIMIT", "limit" },
            { "MARKET", "market" },
        };
