    }

    public override Dictionary<string, object> parseOrder(object order, IDictionary<string, object> market = null)
    {
        //
        //    {
        //        "id": "42154072252",
        //        "asset_pair_name": "SOL-USDT",
        //        "price": "20",
        //        "amount": "0.5",
        //        "filled_amount": "0",
        //        "avg_deal_price": "0",
        //        "side": "ASK",
        //        "state": "PENDING",
        //        "created_at": "2023-09-13T03:42:00Z",
        //        "updated_at": "2023-09-13T03:42:00Z",
        //        "type": "LIMIT",
        //        "stop_price": "0",
        //        "immediate_or_cancel": false,
        //        "post_only": false,
        //        "client_order_id": ''
        //    }
        //
        string? id = this.safeString(order, "id");
        string? marketId = this.safeString(order, "asset_pair_name");
        string? symbol = this.safeSymbol(marketId, market, "-");
        Int64? timestamp = this.parse8601(this.safeString(order, "created_at"));
        string? side = this.safeString(order, "side");
        if (side == "BID")
        {
            side = "buy";
        } else
        {
            side = "sell";
        }
        string? triggerPrice = this.safeString(order, "stop_price");
        if (Precise.stringEq(triggerPrice, "0"))
        {
            triggerPrice = null;
        }
        bool? immediateOrCancel = this.safeBool(order, "immediate_or_cancel");
        string? timeInForce = null;
        if ((immediateOrCancel == true))
        {
            timeInForce = "IOC";
        }
        string? type = this.parseType(this.safeString(order, "type"));
        string? price = this.safeString(order, "price");
        string? amount = null;
        string? filled = null;
        string? cost = null;
        if (type == "market" && side == "buy")
        {
            cost = this.safeString(order, "filled_amount");
        } else
        {
            amount = this.safeString(order, "amount");
            filled = this.safeString(order, "filled_amount");
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", id },
            { "clientOrderId", this.safeString(order, "client_order_id") },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "lastTradeTimestamp", this.parse8601(this.safeString(order, "updated_at")) },
            { "symbol", symbol },
            { "type", type },
            { "timeInForce", timeInForce },
            { "postOnly", this.safeBool(order, "post_only") },
            { "side", side },
            { "price", price },
            { "triggerPrice", triggerPrice },
            { "amount", amount },
            { "cost", cost },
            { "average", this.safeString(order, "avg_deal_price") },
            { "filled", filled },
            { "remaining", null },
            { "status", this.parseOrderStatus(this.safeString(order, "state")) },
            { "fee", null },
            { "trades", null },
        }, market);
    }

