    public override Int64 nonce()
    {
        Int64? exchangeTimeCorrection = (this.safeInteger(this.options, "exchangeMillisecondsCorrection", 0) * 1000000);
        return ((Int64)((object)(this.sum((this.microseconds() * 1000), exchangeTimeCorrection)))!);
    }

    public override Dictionary<string, object> sign(object path, object api = null, string method = null, object parameters = null, object headers = null, object body = null)
    {
        api ??= "public";
        method ??= "GET";
        parameters ??= new Dictionary<string, object>();
        string? bodySigned = null;
        object query = this.omit(parameters, this.extractParams(path));
        string? apiUrl = this.safeString((this.urls != null && ((IDictionary<string, object>)this.urls).ContainsKey("api") ? ((IDictionary<string, object>)this.urls)["api"] : null), api);
        if ((apiUrl == null))
        {
            throw new ExchangeError ((this.id + " sign() has no API URL for this endpoint")) ;
        }
        object baseUrl = this.implodeHostname(apiUrl);
        object url = add(add(baseUrl, "/"), this.implodeParams(path, parameters));
        Dictionary<string, object> headersValue = new Dictionary<string, object>() {};
        if (isEqual(api, "public") || isEqual(api, "webExchange") || isEqual(api, "contractPublic"))
        {
            if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
            {
                url = add(url, ("?" + this.urlencode(query)));
            }
        } else
        {
            this.checkRequiredCredentials();
            string nonce = this.nonce().ToString();
            Dictionary<string, object> request = new Dictionary<string, object>() {
                { "type", "OpenAPIV2" },
                { "sub", this.apiKey },
                { "nonce", nonce },
            };
            string token = jwt(request, this.encode(this.secret), sha256);
            headersValue["Authorization"] = ("Bearer " + token);
            if ((method == "GET"))
            {
                if ((new List<object>(((IDictionary<string,object>)query).Keys)).Count > 0)
                {
                    url = add(url, ("?" + this.urlencode(query)));
                }
            } else if ((method == "POST"))
            {
                headersValue["Content-Type"] = "application/json";
                bodySigned = this.json(query);
            }
        }
        headersValue["User-Agent"] = ((("ccxt/" + this.id) + "-") + this.version);
        object bodyResolved = ((bodySigned == null)) ? body : bodySigned;
        return new Dictionary<string, object>() {
            { "url", url },
            { "method", method },
            { "body", bodyResolved },
            { "headers", headersValue },
        };
    }

    /**
     * @method
     * @name bigone#fetchDepositAddress
     * @description fetch the deposit address for a currency associated with this account
     * @see https://open.big.one/docs/spot_deposit.html#get-deposite-address-of-one-asset-of-user
     * @param {string} code unified currency code
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} an [address structure]{@link https://docs.ccxt.com/?id=address-structure}
     */
    public async override Task<ccxt.DepositAddress> FetchDepositAddress(string code, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> currency = this.currency(code);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "asset_symbol", (currency.ContainsKey("id") ? currency["id"] : null) },
        };
        IList<object> networkCodeparamsOmittedVariable = (IList<object>)this.handleNetworkCodeAndParams(parameters);
        string? networkCode = (string)networkCodeparamsOmittedVariable[0];
        IDictionary<string, object> paramsOmitted = ((IDictionary<string, object>)networkCodeparamsOmittedVariable[1]);
        Dictionary<string, object> response = await this.privateGetAssetsAssetSymbolAddress(this.extend(request, paramsOmitted));
        //
        // the actual response format is not the same as the documented one
        // the data key contains an array in the actual response
        //
        //     {
        //         "code":0,
        //         "message":"",
        //         "data":[
        //             {
        //                 "id":5521878,
        //                 "chain":"Bitcoin",
        //                 "value":"1GbmyKoikhpiQVZ1C9sbF17mTyvBjeobVe",
        //                 "memo":""
        //             }
        //         ]
        //     }
        //
        List<object> data = this.safeList(response, "data", new List<object>() {});
        int dataLength = data.Count;
        if (dataLength < 1)
        {
            throw new ExchangeError ((this.id + " fetchDepositAddress() returned empty address response")) ;
        }
        Dictionary<string, object> chainsIndexedById = this.indexBy(data, "chain");
        object selectedNetworkId = this.selectNetworkIdFromRawNetworks(code, networkCode, chainsIndexedById);
        IDictionary<string, object> addressObject = this.safeDict(chainsIndexedById, selectedNetworkId, new Dictionary<string, object>() {});
        string? address = this.safeString(addressObject, "value");
        string? tag = this.safeString(addressObject, "memo");
        this.checkAddress(address);
        return ccxt.BaseExchange.ToDepositAddress(new Dictionary<string, object>() {             { "info", response },             { "currency", code },             { "network", this.networkIdToCode(selectedNetworkId, code) },             { "address", address },             { "tag", tag },         });
    }

    public virtual string? parseTransactionStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "WITHHOLD", "ok" },
            { "UNCONFIRMED", "pending" },
            { "CONFIRMED", "ok" },
            { "COMPLETED", "ok" },
            { "PENDING", "pending" },
        };
        return this.safeString(statuses, status, status);
    }

    public override Dictionary<string, object> parseTransaction(object transaction, object currency = null)
    {
        //
        // fetchDeposits
        //
        //     {
        //         "amount": "25.0",
        //         "asset_symbol": "BTS"
        //         "confirms": 100,
        //         "id": 5,
        //         "inserted_at": "2018-02-16T11:39:58.000Z",
        //         "is_internal": false,
        //         "kind": "default",
        //         "memo": "",
        //         "state": "WITHHOLD",
        //         "txid": "72e03037d144dae3d32b68b5045462b1049a0755",
        //         "updated_at": "2018-11-09T10:20:09.000Z",
        //     }
        //
        // fetchWithdrawals
        //
        //     {
        //         "amount": "5",
        //         "asset_symbol": "ETH",
        //         "completed_at": "2018-03-15T16:13:45.610463Z",
        //         "customer_id": "10",
        //         "id": 10,
        //         "inserted_at": "2018-03-15T16:13:45.610463Z",
        //         "is_internal": true,
        //         "note": "2018-03-15T16:13:45.610463Z",
        //         "state": "CONFIRMED",
        //         "target_address": "0x4643bb6b393ac20a6175c713175734a72517c63d6f7"
        //         "txid": "0x4643bb6b393ac20a6175c713175734a72517c63d6f73a3ca90a15356f2e967da0",
        //     }
        //
        // withdraw
        //
        //     {
        //         "id":1077391,
        //         "customer_id":1082679,
        //         "amount":"21.9000000000000000",
        //         "txid":"",
        //         "is_internal":false,
        //         "kind":"on_chain",
        //         "state":"PENDING",
        //         "inserted_at":"2020-06-03T00:50:57+00:00",
        //         "updated_at":"2020-06-03T00:50:57+00:00",
        //         "memo":"",
        //         "target_address":"rDYtYT3dBeuw376rvHqoZBKW3UmvguoBAf",
        //         "fee":"0.1000000000000000",
        //         "asset_symbol":"XRP"
        //     }
        //
        string? currencyId = this.safeString(transaction, "asset_symbol");
        string? code = this.safeCurrencyCode(currencyId);
        string? id = this.safeString(transaction, "id");
        double? amount = this.safeNumber(transaction, "amount");
        string? status = this.parseTransactionStatus(this.safeString(transaction, "state"));
        Int64? timestamp = this.parse8601(this.safeString(transaction, "inserted_at"));
        Int64? updated = this.parse8601(this.safeString2(transaction, "updated_at", "completed_at"));
        string? txid = this.safeString(transaction, "txid");
        string? address = this.safeString(transaction, "target_address");
        string? tag = this.safeString(transaction, "memo");
        string type = "deposit";
        if ((transaction != null && ((IDictionary<string, object>)transaction).ContainsKey("customer_id")))
        {
            type = "withdrawal";
        }
        bool? intern = this.safeBool(transaction, "is_internal");
        return new Dictionary<string, object>() {
            { "info", transaction },
            { "id", id },
            { "txid", txid },
            { "timestamp", timestamp },
            { "datetime", this.iso8601(timestamp) },
            { "network", null },
            { "addressFrom", null },
            { "address", null },
            { "addressTo", address },
            { "tagFrom", null },
            { "tag", tag },
            { "tagTo", null },
            { "type", type },
            { "amount", amount },
            { "currency", code },
            { "status", status },
            { "updated", updated },
            { "fee", null },
            { "comment", null },
            { "internal", intern },
        };
    }

