    /**
     * @method
     * @name bigone#transfer
     * @description transfer currency internally between wallets on the same account
     * @see https://open.big.one/docs/spot_transfer.html#transfer-of-user
     * @param {string} code unified currency code
     * @param {float} amount amount to transfer
     * @param {string} fromAccount 'SPOT', 'FUND', or 'CONTRACT'
     * @param {string} toAccount 'SPOT', 'FUND', or 'CONTRACT'
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [transfer structure]{@link https://docs.ccxt.com/?id=transfer-structure}
     */
    public async override Task<ccxt.TransferEntry> Transfer(string code, double amount, string fromAccount, string toAccount, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> currency = this.currency(code);
        IDictionary<string, object> accountsByType = this.safeDict(this.options, "accountsByType", new Dictionary<string, object>() {});
        string? fromId = this.safeString(accountsByType, fromAccount, fromAccount);
        string? toId = this.safeString(accountsByType, toAccount, toAccount);
        string? guid = this.safeString(parameters, "guid", this.uuid());
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (currency.ContainsKey("id") ? currency["id"] : null) },
            { "amount", this.currencyToPrecision(code, amount) },
            { "from", fromId },
            { "to", toId },
            { "guid", guid },
        };
        Dictionary<string, object> response = await this.privatePostTransfer(this.extend(request, parameters));
        //
        //     {
        //         "code": 0,
        //         "data": null
        //     }
        //
        Dictionary<string, object> transfer = this.parseTransfer(response, currency);
        IDictionary<string, object> transferOptions = this.safeDict(this.options, "transfer", new Dictionary<string, object>() {});
        bool? fillResponseFromRequest = this.safeBool(transferOptions, "fillResponseFromRequest", true);
        if ((fillResponseFromRequest == true))
        {
            transfer["fromAccount"] = fromAccount;
            transfer["toAccount"] = toAccount;
            transfer["amount"] = amount;
            transfer["id"] = guid;
        }
        return ccxt.BaseExchange.ToTransferEntry(transfer);
    }

    public override Dictionary<string, object> parseTransfer(object transfer, IDictionary<string, object> currency = null)
    {
        //
        //     {
        //         "code": 0,
        //         "data": null
        //     }
        //
        string? code = this.safeString(transfer, "code");
        return new Dictionary<string, object>() {
            { "info", transfer },
            { "id", null },
            { "timestamp", null },
            { "datetime", null },
            { "currency", null },
            { "amount", null },
            { "fromAccount", null },
            { "toAccount", null },
            { "status", this.parseTransferStatus(code) },
        };
    }

    public virtual string? parseTransferStatus(string? status)
    {
        Dictionary<string, object> statuses = new Dictionary<string, object>() {
            { "0", "ok" },
        };
        return this.safeString(statuses, status, "failed");
    }

    /**
     * @method
     * @name bigone#withdraw
     * @description make a withdrawal
     * @see https://open.big.one/docs/spot_withdrawal.html#create-withdrawal-of-user
     * @param {string} code unified currency code
     * @param {float} amount the amount to withdraw
     * @param {string} address the address to withdraw to
     * @param {string} tag
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object} a [transaction structure]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<ccxt.Transaction> Withdraw(string code, double amount, string address, string tag = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        IList<object> tagWithdrawTagparamsWithdrawTagVariable = (IList<object>)this.handleWithdrawTagAndParams(tag, parameters);
        var tagWithdrawTag = tagWithdrawTagparamsWithdrawTagVariable[0];
        IDictionary<string, object> paramsWithdrawTag = ((IDictionary<string, object>)tagWithdrawTagparamsWithdrawTagVariable[1]);
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> currency = this.currency(code);
        Dictionary<string, object> request = new Dictionary<string, object>() {
            { "symbol", (currency.ContainsKey("id") ? currency["id"] : null) },
            { "target_address", address },
            { "amount", this.currencyToPrecision(code, amount) },
        };
        if ((tagWithdrawTag != null))
        {
            request["memo"] = tagWithdrawTag;
        }
        IList<object> networkCodeparamsNetworkCodeVariable = (IList<object>)this.handleNetworkCodeAndParams(paramsWithdrawTag);
        string? networkCode = (string)networkCodeparamsNetworkCodeVariable[0];
        var paramsNetworkCode = networkCodeparamsNetworkCodeVariable[1];
        if ((networkCode != null))
        {
            request["gateway_name"] = this.networkCodeToId(networkCode, (currency.ContainsKey("code") ? currency["code"] : null));
        }
        // requires write permission on the wallet
        Dictionary<string, object> response = await this.privatePostWithdrawals(this.extend(request, paramsNetworkCode));
        //
        //     {
        //         "code":0,
        //         "message":"",
        //         "data":{
        //             "id":1077391,
        //             "customer_id":1082679,
        //             "amount":"21.9000000000000000",
        //             "txid":"",
        //             "is_internal":false,
        //             "kind":"on_chain",
        //             "state":"PENDING",
        //             "inserted_at":"2020-06-03T00:50:57+00:00",
        //             "updated_at":"2020-06-03T00:50:57+00:00",
        //             "memo":"",
        //             "target_address":"rDYtYT3dBeuw376rvHqoZBKW3UmvguoBAf",
        //             "fee":"0.1000000000000000",
        //             "asset_symbol":"XRP"
        //         }
        //     }
        //
        IDictionary<string, object> data = this.safeDict(response, "data", new Dictionary<string, object>() {});
        return ccxt.BaseExchange.ToTransaction(this.parseTransaction(data, currency));
    }

    public override object handleErrors(object httpCode, string reason, string url, string method, object headers, object body, object response, Dictionary<string, object> requestHeaders, object requestBody)
    {
        if ((response == null))
        {
            return null;  // fallback to default error handler
        }
        //
        //      {"code":10013,"message":"Resource not found"}
        //      {"code":40004,"message":"invalid jwt"}
        //
        string? code = this.safeString(response, "code");
        string? message = this.safeString(response, "message");
        if ((code != "0") && ((code != null)))
        {
            string feedback = ((this.id + " ") + (body));
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), message, feedback);
            this.throwExactlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("exact") ? ((IDictionary<string, object>)this.exceptions)["exact"] : null), code, feedback);
            this.throwBroadlyMatchedException((this.exceptions != null && ((IDictionary<string, object>)this.exceptions).ContainsKey("broad") ? ((IDictionary<string, object>)this.exceptions)["broad"] : null), message, feedback);
            throw new ExchangeError (feedback) ;
        }
        return null;
    }
